{
  "name": "opencode-9router-model-sync",
  "version": "0.1.1",
  "description": "OpenCode plugin that syncs a self-hosted 9router /v1/models catalog into your provider config",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "LICENSE",
    "README.md"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "tsx --test test/**/*.test.ts",
    "prepublishOnly": "npm run typecheck && npm run test && npm run build"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "9router",
    "models",
    "ai"
  ],
  "author": "jolangker",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jolangker/opencode-9router-model-sync.git"
  },
  "bugs": {
    "url": "https://github.com/jolangker/opencode-9router-model-sync/issues"
  },
  "homepage": "https://github.com/jolangker/opencode-9router-model-sync#readme",
  "engines": {
    "node": ">=20"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/node": "^22.15.0",
    "tsx": "^4.19.0",
    "typescript": "^5.8.0"
  }
}
